solution_md:
Compute the cosine with the full formula, then place it on the scale: 1 same, −1 opposite, 0 orthogonal. The tolerance absorbs rounding such as `0.9999999999999998`. A zero vector has no direction, so refuse it.

```python
import math

TOL = 1e-9


def cosine_sim(a, b):
    if len(a) != len(b):
        raise ValueError("vectors must have the same length")
    dot = sum(x * y for x, y in zip(a, b))
    norm_a = math.sqrt(sum(x * x for x in a))
    norm_b = math.sqrt(sum(y * y for y in b))
    if norm_a == 0 or norm_b == 0:
        raise ValueError("cosine is undefined for a zero vector")
    return dot / (norm_a * norm_b)


def classify_pair(a, b):
    c = cosine_sim(a, b)
    if c >= 1 - TOL:
        return "same"
    if c <= -1 + TOL:
        return "opposite"
    if abs(c) <= TOL:
        return "orthogonal"
    return "other"
